static double Calc(double a, double b, char op) {
  if(op=='+') return a+b;
  if(op=='-') return a-b;
  if(op=='*') return a*b;
  if(op=='/') return a/b;
  return 0;
}
Console.WriteLine(Calc(10, 2, '/'));

using System.Collections.Generic;
class ToDo {
  public List<string> tasks = new List<string>();
  public void Add(string t) { tasks.Add(t); }
}
static void Main() {
  ToDo t = new ToDo();
  t.Add("Study");
  t.Add("Sleep");
  Console.WriteLine(t.tasks[0]);
}

using System.Collections.Generic;
class ToDo {
  public List<string> tasks = new List<string>() { "Study" };
  public void Complete(string t) { tasks.Remove(t); }
}
static void Main() {
  ToDo t = new ToDo();
  t.Complete("Study");
  Console.WriteLine(t.tasks.Count);
}

